func snapshotOwner(r *repo, path string) string {
	dir := []byte(r.Config.Dir)
	for i, c := range dir {
		if c == '\\' {
			dir[i] = '/'
		}
	}
	prefix := string(dir) + "/.versions/"
	if len(path) < len(prefix) || path[:len(prefix)] != prefix {
		return ""
	}
	rest := path[len(prefix):]
	for i := 0; i < len(rest); i++ {
		if rest[i] == '/' {
			if i == 0 {
				return ""
			}
			return rest[:i]
		}
	}
	return ""
}

